import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"ランキングと競技を理解する","description":"","frontmatter":{"title":"ランキングと競技を理解する","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"ja","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1c45cf6e9355092d95dc9f90025b2965e0a6a4cddb453fb25680192ab41e873c","translationRevision":"62a33f021f41b45102866afaa423702348436a09e0a026f1536c0929eec74158","order":30},"headers":[],"relativePath":"ja/user/points/rankings.md","filePath":"ja/user/points/rankings.md","lastUpdated":1795731074000}`),s={name:`ja/user/points/rankings.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="understand-rankings-and-competitions" tabindex="-1">ランキングと競技を理解する <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to “ランキングと競技を理解する”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目的と前提条件”">​</a></h2><p>適切な順位表示を選び、開発中のランキング画面の制限を理解します。意味のあるスコアにはイベントの受信が必要です。現在の視聴者を確認するだけなら、通常の <a href="./rules.html">ポイント</a> の順位表や <a href="./../live/feed.html">ライブフィード</a> の上位視聴者パネルから始めます。</p><h2 id="use-the-right-view" tabindex="-1">適切な表示を使う <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to “適切な表示を使う”">​</a></h2><ol><li><strong>ポイント</strong> で視聴者を検索し、ポイント、レベル、視聴者 ID で並べ替えます。手動調整と付与を比べる前に更新します。</li><li><strong>ライブフィード</strong> の順位パネルを確認します。ポイント残高表とは独立してランキングエンジンのスナップショットを受け取る場合があります。</li><li>オーバーレイでは <a href="./../overlays/">オーバーレイ</a> のランキング種別を選び、ソースの設定を確認します。出力には設定済みランキングソースが必要です。</li></ol><p>専用の <strong>ランキングとコンテスト</strong> 画面は実験段階です。ルートは <code>#/rankings</code> ですが、メインナビゲーションには意図的に表示せず、起動タブとしても復元しません。サイドバー項目がなくても、ルートやエンジンが削除されたわけではありません。</p><h2 id="configure-an-experimental-ranking" tabindex="-1">実験的ランキングを設定する <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to “実験的ランキングを設定する”">​</a></h2><p>画面が利用できる環境では、配信者1人、ルーム1つ、ユーザー単位のグループ化、セッション期間で始めます。<code>tiktok.like</code> / <code>like.count</code> など提供されている指標を1つ、重み <code>1</code> で追加します。結果件数を控えめにして定義を作成します。フォームは移動期間と日次期間にも対応し、期間・イベント数の上限やタイムゾーン差を明示できます。</p><p>ソースを増やす前にスナップショットを読みます。一時停止・再開はランキングの収集に作用し、リセットは意図的にランキング状態を消します。競技の設定と投票関連ソースには独自のグループ化規則があります。ポイントのリセットで競技もリセットされる、またはすべての独自グループが全指標で使えるとは考えないでください。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “期待される結果と提供状況”">​</a></h2><p>通常の順位表は利用でき、専用管理ページは実験段階です。スコアはホストが計算し、表示フィードの行数から算出しません。このガイドは実配信・OBS の動作や競技の全組み合わせを確認するものではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to “問題が起きたとき”">​</a></h2><p>空のスコアでは配信者、ルーム、ソースの有効状態、期間、一時停止を確認します。非対応のソース・グループの組み合わせは架空のフィールド名で補わず削除します。リセット前に重要データを<a href="./../preferences/backups.html">バックアップ</a> し、報告には定義 ID と診断コードを含めます。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to “運用の詳細”">​</a></h2><p>Points 表は 100 人を取得し、その行だけを検索・並べ替えます。更新や名前順への変更でデータベース全体を検索するわけではありません。フィードのランキングは配信者・ルームのセッションごとに 10 行を表示し、Top はギフトのダイヤ、Likes はいいね数を集計します。追跡上限は 5,000 人です。保存ポイントとは単位と期間を分けて比較してください。</p><p>実際の設定に触れる前にインタラクティブに試せます:</p>`,16),t(d,{scenario:`points`,locale:`ja`,panel:`points`,title:`ランキングと視聴者ポイントを試す`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">コマンドライン操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “コマンドライン操作”">​</a></h2><p>このガイドのすべての操作はCLIからも利用できます——オフライン、スクリプト可能、エージェント対応。使用法の行はパーサー構文であり、すべての言語で英語のままです。</p><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>ランキング定義を一覧表示</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>ランキング定義で利用可能なメトリクス</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>ランキング定義を作成</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>ランキング定義を更新</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>ランキングを1つ読み取る</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>ランキングの現在の順位</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>ランキングを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>蓄積状態をリセット <strong>破壊的</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>蓄積を一時停止</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>蓄積を再開</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>外部の貢献を追加</td></tr></tbody></table><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>コンペティションを一覧表示</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>コンペティションを1つ読み取る</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>コンペティションを作成</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>コンペティションを更新</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>コンペティションを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>現在のコンペティション状態</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>最終または中間結果</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>コンペティションアクションを記録</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>アクションを不確実としてフラグ</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>不確実なアクションを解決</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>コンペティションを開始</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>コンペティションを終了 <strong>破壊的</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>勝者候補</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>勝者を選択</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>コンペティションを一時停止</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>コンペティションを再開</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>コンペティションをキャンセル <strong>破壊的</strong></td></tr></tbody></table><p>規約、JSON出力、破壊的操作のマーカーについては<a href="./../../developer/cli.html">完全なコマンドリファレンス</a>を参照してください。</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};